def symcheck(g,mode):
    H=len(g);W=len(g[0])
    if mode=='hv': return all(g[i][j]==g[H-1-i][j] for i in range(H) for j in range(W))
    if mode=='hr': return all(g[i][j]==g[i][W-1-j] for i in range(H) for j in range(W))
    if mode=='rot180': return all(g[i][j]==g[H-1-i][W-1-j] for i in range(H) for j in range(W))
    if mode=='diag': return all(g[i][j]==g[j][i] for i in range(min(H,W)) for j in range(min(H,W)))
