# noise cell gets absorbed into a neighboring big object if it's "enclosed" in the sense: majority of its 8-neighborhood is that object's color AND at least 2 of the 4 orth neighbors share one non-bg color... test combos quickly.
def solve(inp, rule):
    g=[r[:] for r in inp]; H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    def comp_at(y,x):
        st=[(y,x)]; cells=[]
        while st:
            yy,xx=st.pop()
            if seen[yy][xx]: continue
            seen[yy][xx]=True; cells.append((yy,xx))
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=yy+dy,xx+dx
                if 0<=ny<H and 0<=nx<W and g[ny][nx]==g[yy][xx] and not seen[ny][nx]: st.append((ny,nx))
        return cells
    obj=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j] and len(comp_at(i,j))>=4:
                for y,x in comp_at(i,j): obj.add((y,x))
    out=g
    for i in range(H):
        for j in range(W):
            if (i,j) not in obj:
                nb8=[inp[r][c] for r in range(max(0,i-1),min(H,i+2)) for c in range(max(0,j-1),min(W,j+2)) if (r,c)!=(i,j)]
                m=Counter(nb8).most_common()
                v=m[0][0]
                orth_same=sum(1 for dy,dx in((1,0),(-1,0),(0,1),(0,-1)) if 0<=i+dy<H and 0<=j+dx<W and inp[i+dy][j+dx]==v)
                out[i][j]= v if rule(orth_same,m,v,bg) else inp[i][j]
    return out
